create table apx_demo_departments (
   department_id number generated by default on null as identity
  ,dept_code varchar2(20) not null
  ,dept_name varchar2(100) not null
  ,active_yn varchar2(1) default 'Y'
  ,created_by varchar2(255)
  ,created_on date
  ,updated_by varchar2(255)
  ,updated_on date
  ,constraint apx_demo_departments_pk primary key (department_id)
  ,constraint apx_demo_departments_u1 unique (dept_code)
  ,constraint apx_demo_departments_ck1 check (active_yn in ('Y', 'N'))
);

create table apx_demo_items (
   item_id number generated by default on null as identity
  ,item_code varchar2(30) not null
  ,item_name varchar2(200) not null
  ,category varchar2(20) not null
  ,uom varchar2(10) not null
  ,std_price number default 0 not null
  ,active_yn varchar2(1) default 'Y'
  ,created_by varchar2(255)
  ,created_on date
  ,updated_by varchar2(255)
  ,updated_on date
  ,constraint apx_demo_items_pk primary key (item_id)
  ,constraint apx_demo_items_u1 unique (item_code)
  ,constraint apx_demo_items_ck1 check (category in ('ATK', 'IT', 'CONSUMABLE'))
  ,constraint apx_demo_items_ck2 check (std_price >= 0)
  ,constraint apx_demo_items_ck3 check (active_yn in ('Y', 'N'))
);

create table apx_demo_requests (
   request_id number generated by default on null as identity
  ,request_no varchar2(30)
  ,department_id number not null
  ,request_date date not null
  ,need_date date
  ,purpose varchar2(300) not null
  ,notes varchar2(1000)
  ,status varchar2(20) default 'DRAFT' not null
  ,created_by varchar2(255)
  ,created_on date
  ,updated_by varchar2(255)
  ,updated_on date
  ,constraint apx_demo_requests_pk primary key (request_id)
  ,constraint apx_demo_requests_u1 unique (request_no)
  ,constraint apx_demo_requests_ck1 check (status in ('DRAFT', 'SUBMITTED', 'APPROVED', 'REJECTED', 'CANCELLED', 'FULFILLED', 'CLOSED'))
);

create table apx_demo_request_lines (
   line_id number generated by default on null as identity
  ,request_id number not null
  ,item_id number not null
  ,qty number not null
  ,unit_price number default 0 not null
  ,line_amount number generated always as (qty * unit_price) virtual
  ,created_by varchar2(255)
  ,created_on date
  ,updated_by varchar2(255)
  ,updated_on date
  ,constraint apx_demo_request_lines_pk primary key (line_id)
  ,constraint apx_demo_request_lines_ck1 check (qty >= 0)
  ,constraint apx_demo_request_lines_ck2 check (unit_price >= 0)
);

-- foreign keys & index
alter table apx_demo_requests add constraint apx_demo_requests_fk1 foreign key (department_id) references apx_demo_departments (department_id);
create index apx_demo_requests_n1 on apx_demo_requests (department_id);
alter table apx_demo_request_lines add constraint apx_demo_request_lines_fk1 foreign key (request_id) references apx_demo_requests (request_id) on delete cascade;
create index apx_demo_request_lines_n1 on apx_demo_request_lines (request_id);
alter table apx_demo_request_lines add constraint apx_demo_request_lines_fk2 foreign key (item_id) references apx_demo_items (item_id);
create index apx_demo_request_lines_n2 on apx_demo_request_lines (item_id);
